import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"音频与设备","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/audio.md","filePath":"zh/troubleshooting/audio.md","lastUpdated":1792936228000}'),n={name:"zh/troubleshooting/audio.md"};function l(i,o,a,g,h,u){return t(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="音频与设备" tabindex="-1">音频与设备 <a class="header-anchor" href="#音频与设备" aria-label="Permalink to &quot;音频与设备&quot;">​</a></h1><p>本页用于 MeetCue 听不到你、听不到其他与会者，或听错了声音的情况。按步骤排查时，可以打开 <strong>设置 › 音频 › 测试电平</strong> 同时观察两个电平条。</p><h2 id="no-system-sound" tabindex="-1">系统声音电平一直不动 <a class="header-anchor" href="#no-system-sound" aria-label="Permalink to &quot;系统声音电平一直不动 {#no-system-sound}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>会议软件使用的播放设备不是 Windows 的默认输出设备。</li><li>当前没有声音在播放，或会议软件被静音。</li><li>其他程序以独占模式占用了输出设备（<a href="/meetcue/zh/troubleshooting/error-codes#mc-aud-001">MC-AUD-001</a>）。</li><li>声卡驱动不支持环回采集（<a href="/meetcue/zh/troubleshooting/error-codes#mc-aud-005">MC-AUD-005</a>）。</li></ol><p><strong>检查</strong></p><ol><li>打开 Windows <strong>设置 › 系统 › 声音</strong>，记下输出设备。</li><li>在会议软件的音频设置里查看它使用的扬声器。</li><li>在浏览器中播放一段视频，观察系统声音电平条。</li></ol><p><strong>解决</strong></p><ol><li>把会议软件的扬声器设为 <strong>默认</strong>，或与 Windows 输出设备一致。</li><li>如果提示 MC-AUD-001：打开 <strong>声音 › 更多声音设置</strong>，打开该设备的 <strong>属性 › 高级</strong>，取消勾选 <strong>允许应用程序独占控制该设备</strong>，然后重启占用设备的程序。</li><li>从电脑厂商处更新声卡驱动。</li></ol><div class="tip custom-block"><p class="custom-block-title">用耳机测试</p><p>用外放测试时，麦克风会录到外放声音，麦克风电平条会跳动，但这并不说明系统声音采集正常。请把扬声器静音或戴上耳机，只看系统声音电平条。<code>MeetCue.exe --self-test</code> 检查的正是这一点。</p></div><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="no-microphone" tabindex="-1">麦克风电平一直不动 <a class="header-anchor" href="#no-microphone" aria-label="Permalink to &quot;麦克风电平一直不动 {#no-microphone}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>Windows 禁止桌面应用访问麦克风（<a href="/meetcue/zh/troubleshooting/error-codes#mc-aud-002">MC-AUD-002</a>）。</li><li>MeetCue 使用的麦克风不是你说话用的那个。</li><li>麦克风被硬件按键或驱动静音。</li></ol><p><strong>检查</strong></p><ol><li>打开 Windows <strong>设置 › 隐私和安全性 › 麦克风</strong>。</li><li>在 MeetCue 中打开 <strong>设置 › 音频</strong>，查看 <strong>麦克风（我）</strong>。</li></ol><p><strong>解决</strong></p><ol><li>打开 <strong>麦克风访问权限</strong> 和 <strong>允许桌面应用访问你的麦克风</strong>。</li><li>在 <strong>麦克风（我）</strong> 中选择你的麦克风，或选 <strong>系统默认</strong> 并在 Windows 中设置默认设备。</li><li>如果笔记本的麦克风静音键指示灯亮着，按一下取消静音。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="device-changed" tabindex="-1">换了耳机或音箱后采集停止 <a class="header-anchor" href="#device-changed" aria-label="Permalink to &quot;换了耳机或音箱后采集停止 {#device-changed}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>默认设备发生变化，采集正在重建（<a href="/meetcue/zh/troubleshooting/error-codes#mc-aud-004">MC-AUD-004</a>）。</li><li>新设备被其他程序独占。</li></ol><p><strong>检查</strong></p><ol><li>留意面板上“音频设备已切换，采集已自动恢复”的提示。</li><li>切换后观察电平条几秒钟。</li></ol><p><strong>解决</strong></p><ol><li>等两三秒，MeetCue 会自动重建采集。</li><li>如果电平条仍不动，按 <code>Ctrl+Alt+Space</code> 暂停再继续。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="echo" tabindex="-1">对方的话把我的要点勾掉了 <a class="header-anchor" href="#echo" aria-label="Permalink to &quot;对方的话把我的要点勾掉了 {#echo}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>你在用外放，麦克风录到了其他与会者的声音。</li><li>麦克风很灵敏，或离扬声器太近。</li></ol><p><strong>检查</strong></p><ol><li>查看对话：标为 <strong>我</strong> 的句子在重复别人刚说的话。</li></ol><p><strong>解决</strong></p><ol><li>戴耳机，这是最可靠的办法。</li><li>调低扬声器音量，或让麦克风远离扬声器。</li><li>把 <strong>设置 › 音频 › 高级 › 人声检测门限</strong> 调高一点。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="bluetooth" tabindex="-1">使用蓝牙耳机时播放音质变差 <a class="header-anchor" href="#bluetooth" aria-label="Permalink to &quot;使用蓝牙耳机时播放音质变差 {#bluetooth}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>程序打开蓝牙耳机的麦克风时，Windows 会把耳机切换到通话模式，所有声音的音质都会下降。</li></ol><p><strong>检查</strong></p><ol><li>所选麦克风看起来是蓝牙设备时，<strong>设置 › 音频</strong> 会显示提醒。</li></ol><p><strong>解决</strong></p><ol><li>在 <strong>麦克风（我）</strong> 中选择电脑内置麦克风，耳机只用来听。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p>',43)])])}const d=e(n,[["render",l]]);export{p as __pageData,d as default};
